contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public payable {
        require(_val > 0);

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setReverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setReverted = true;
        } else {
            setReverted = false;
        }

        assert(setReverted && c.MinSum() == 0);
    }
}

