pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val) internal {
        vm.assume(_val > 0);
        try c.Initialized() {} catch { return; }
        bool setReverted;
        try c.SetMinSum(_val) {
            setReverted = false;
        } catch {
            setReverted = true;
        }
        assertTrue(setReverted && c.MinSum() == 0);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
